mapper.select:
select answer_id
from biz_county_exam_answer
where student_answer = #{resource}
   or file_path = #{resource}
   or preview_path = #{resource}
order by answer_id desc
limit 1

select count(1)
from biz_county_exam_paper_question pq
where pq.file_path = #{resource} or pq.preview_path = #{resource}
